            {'who': 'HOUSEHOLDER',
             'vi': 'Tôi không chắc nữa.',
             'ko': '글쎄요.',
             'zh': '我不肯定。',
             'en': 'I’m not sure I follow you.',
             'ja': 'そうかなぁ。',
             'de': 'Wie meinen Sie das jetzt?',
             'fr': 'Je ne sais pas...',
             'pl': 'No nie wiem.'},
            {'who': 'PUBLISHER',
             'vi': 'Xin mời anh xem xét một câu Kinh Thánh khác nói về đời sống tương lai trên đất. Mời anh đọc Khải '
                   'huyền 21:4. Liên quan đến những người sẽ sống trong tương lai, câu này nói: “Ngài [Đức Chúa Trời] '
                   'sẽ lau hết nước mắt trên mắt họ, sẽ không còn sự chết, than van, khóc lóc hay đau đớn nữa. Những '
                   'điều trước kia nay đã qua rồi”. Chẳng phải đó là một viễn cảnh tuyệt vời sao?',
             'ko': '그럼, 앞으로 이 땅에서 누릴 삶에 관해 알려 주는 다른 성구를 살펴볼까요? 계시록 21:4에서는 미래에 사람들이 누리게 될 삶에 관해 이렇게 알려 줍니다. “그분[하느님]은 '
                   '그들의 눈에서 모든 눈물을 닦아 주실 것이다. 더 이상 죽음이 없고, 슬픔과 부르짖음과 고통도 더는 없을 것이다. 이전 것들이 다 사라져 버린 것이다.” 정말 가슴 설레는 '
                   '전망이 아닙니까?',
             'zh': '那麼，不如讓我們看看另一節經文，那裡也談到人將來在地上會過怎樣的生活。啟示錄21:4說：「上帝要擦掉他們的每一滴眼淚，不再有死亡，也不再有哀痛、呼號、痛苦。從前的事已經過去了。」你希望看到這段話實現嗎？',
             'en': 'Well, consider what another portion of the Bible says about life on earth in the future. Let’s '
                   'read Revelation 21:4. Concerning people who will live at that future time, the verse says: “He '
                   '[God] will wipe out every tear from their eyes, and death will be no more, neither will mourning '
                   'nor outcry nor pain be anymore. The former things have passed away.” Isn’t that an appealing '
                   'prospect?',
             'ja': 'では，将来の地上での生活について，別の聖句が何と述べているか，啓示 '
                   '21章4節を読んでみましょう。その時生きている人々に関して，こう述べられています。「神は人々の目から全ての涙を拭い去ります。もはや死はなくなり，悲しみも嘆きも苦痛もなくなります。以前のものは過ぎ去ったのです」。そうなったらいいと思われませんか。',
             'de': 'Schauen Sie mal, was an einer anderen Stelle in der Bibel — in Offenbarung 21:4 — über die '
                   'Menschen und das künftige Leben auf der Erde gesagt wird: „Er [Gott] wird jede Träne von ihren '
                   'Augen abwischen, und der Tod wird nicht mehr sein, noch wird Trauer noch Geschrei noch Schmerz '
                   'mehr sein. Die früheren Dinge sind vergangen.“ Klingt das nicht gut?',
             'fr': 'Voyez ce que dit un autre passage de la Bible à propos de la vie sur terre dans l’avenir. Lisons '
                   'Révélation 21:4. Il est dit ici au sujet de ceux qui vivront à cette époque : “ Il [c’est-à-dire '
                   'Dieu] essuiera toute larme de leurs yeux, et la mort ne sera plus ; ni deuil, ni cri, ni douleur '
                   'ne seront plus. Les choses anciennes ont disparu. ” C’est une perspective magnifique, '
                   'n’est-\u200bce pas ?',
             'pl': 'Przeczytajmy Księgę Objawienia 21:4. Powiedziano tu, co w przyszłości czeka ludzi, którzy będą żyć '
                   'na ziemi: „[Bóg] otrze z ich oczu wszelką łzę, i śmierci już nie będzie ani żałości, ani krzyku, '
                   'ani bólu już nie będzie. To, co poprzednie, przeminęło”. Czy to nie wspaniała perspektywa?'},
