            {'who': 'PUBLISHER',
             'vi': 'Chúng ta hãy xem một ví dụ nơi Xuất Ê-díp-tô Ký 3:7. Mời chị đọc câu này.',
             'ko': '한 가지 예를 보여 드릴게요. 탈출기 3:7인데 좀 읽어 주시겠어요?',
             'zh': '出埃及記3:7提到一個例子。可以請你把經文讀出來嗎？',
             'en': 'Let me show you an example here at Exodus 3:7. Would you mind reading that verse?',
             'ja': 'はい，その良い例が，出エジプト記 3章7節にあります。この節を読んでいただけますか。',
             'de': 'Ich zeige Ihnen mal ein Beispiel in 2. Mose 3:7. Hätten Sie Lust, das selbst zu lesen?',
             'fr': 'Voyez par exemple le verset d’Exode 3:7. Vous voulez bien le lire ?',
             'pl': 'Jeśli pani pozwoli, to pokażę inny werset biblijny, z Księgi Wyjścia 3:7. Czy mogłaby pani '
                   'przeczytać?'},
            {'who': 'HOUSEHOLDER',
             'vi': 'Ở đây nói: “Đức Giê-hô-va phán rằng: Ta đã thấy rõ-ràng sự cực-khổ của dân ta tại xứ Ê-díp-tô, và '
                   'có nghe thấu tiếng kêu-rêu vì cớ người đốc-công của nó; phải, ta biết được nỗi đau-đớn của nó”.',
             'ko': '네. “여호와께서 덧붙여 말씀하셨다. ‘나는 이집트에 있는 내 백성의 괴로움을 똑똑히 보았고, 그들에게 일을 시키는 사람들로 말미암은 그들의 부르짖음을 들었다. 나는 그들이 '
                   '겪는 고통을 잘 알고 있기 때문이다.’”',
             'zh': '好的。「耶和華說：『我的子民在埃及的苦況，我實在看見了；他們在監工手下發出的呼號，我也聽見了。我清楚知道他們所受的痛苦。』」',
             'en': 'All right. It says: “And Jehovah added: ‘Unquestionably I have seen the affliction of my people '
                   'who are in Egypt, and I have heard their outcry as a result of those who drive them to work; '
                   'because I well know the pains they suffer.’”',
             'ja': 'いいですよ。「するとエホバはなおもこう言われた。『わたしは，エジプトにいるわたしの民の苦悩を確かに見た。彼らを駆り立てて働かせる者たちゆえのその叫びを聞いた。わたしは彼らの忍ぶ苦痛をよく知っているのである』」。',
             'de': 'Gut. Da steht: „Und Jehova fügte hinzu: ,Zweifellos habe ich die Trübsal meines Volkes, das in '
                   'Ägypten ist, gesehen, und ich habe ihr Geschrei über die gehört, die sie zur Arbeit antreiben; '
                   'denn ich weiß wohl, welche Schmerzen sie leiden.‘\u202f“',
             'fr': 'D’accord. « Et Jéhovah ajouta : “Vraiment, j’ai vu l’affliction de mon peuple qui est en Égypte et '
                   'j’ai entendu leur clameur à cause de ceux qui les poussent au travail, car je connais bien les '
                   'douleurs qu’ils subissent.” »',
             'pl': 'Dobrze. „I Jehowa dodał: ‚Zaiste widziałem uciśnienie mego ludu, który jest w Egipcie, i słyszałem '
                   'ich krzyk z powodu tych, którzy ich poganiają do pracy; gdyż dobrze znam boleści, jakich '
                   'doznają’”.'},
            {'who': 'PUBLISHER',
             'vi': 'Cảm ơn chị. Theo câu này, Đức Chúa Trời có thấy nỗi đau khổ của dân ngài không?',
             'ko': '감사합니다. 이 성구를 보면, 하느님께서 자신의 백성이 겪는 고난을 눈여겨보신다고 할 수 있을까요?',
             'zh': '謝謝。根據這節經文，上帝知道他的子民受苦嗎？',
             'en': 'Thank you. Based on this scripture, does God notice when his people suffer?',
             'ja': 'ありがとうございます。この聖句によれば，神はご自分の民が苦しんでいた時，そのことを知っておられたでしょうか。',
             'de': 'Danke. Wenn Sie das so lesen, was denken Sie: Sieht Gott, wenn Menschen leiden?',
             'fr': 'Merci. D’après ce passage, est-ce que Dieu remarque quand son peuple souffre ?',
             'pl': 'Dziękuję. Czy zgodnie z tymi słowami Bóg zauważa nasze cierpienia?'},
